param([Parameter(Mandatory=$true)][string]$Executable,[switch]$GpuValidation)
$ErrorActionPreference='Stop'
function Get-Sha256Hex([string]$Path){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($Path))).Replace('-','').ToLowerInvariant())}finally{$sha.Dispose()}}
$sourceRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path
$fingerprintFiles=@('engine/native/CMakeLists.txt','engine/native/include/Aevrynd/CharacterPresentation3D.h','engine/native/src/CharacterPresentation3D.cpp','engine/native/src/Engine.cpp','engine/native/tests/CharacterPresentation3DSmoke.cpp','games/character_lab/native/src/CharacterLabGame.cpp','engine/native/include/Aevrynd/EnvironmentCollisionStreaming3D.h','engine/native/src/EnvironmentCollisionStreaming3D.cpp','engine/native/tests/EnvironmentCollisionStreaming3DSmoke.cpp','games/gameplay_lab/game.json','games/gameplay_lab/native/CMakeLists.txt','games/gameplay_lab/native/include/GameplayAnimation3D.h','games/gameplay_lab/native/include/GameplayCombat3D.h','games/gameplay_lab/native/include/GameplayLabGame.h','games/gameplay_lab/native/src/GameplayAnimation3D.cpp','games/gameplay_lab/native/include/GameplayShowcaseEnvironment3D.h','games/gameplay_lab/native/src/GameplayShowcaseEnvironment3D.cpp','games/gameplay_lab/native/include/GameplayObjectPaletteUi3D.h','games/gameplay_lab/native/src/GameplayObjectPaletteUi3D.cpp','games/gameplay_lab/native/src/GameplayLabGame.cpp','games/gameplay_lab/native/src/main.cpp','games/gameplay_lab/native/tests/GameplayCombatAnimationSmoke.cpp','games/gameplay_lab/native/tests/GameplayLabCaptureSmoke.ps1')
$fingerprintInput='';foreach($relative in $fingerprintFiles){$fileHash=Get-Sha256Hex (Join-Path $sourceRoot $relative);$fingerprintInput+="$relative`:$fileHash`n"};$fingerprintSha=[Security.Cryptography.SHA256]::Create();try{$env:AEVRYND_EXPECTED_CHARACTER_FINGERPRINT=([BitConverter]::ToString($fingerprintSha.ComputeHash([Text.Encoding]::UTF8.GetBytes($fingerprintInput))).Replace('-','').ToLowerInvariant())}finally{$fingerprintSha.Dispose()}
if($GpuValidation){$env:AEVRYND_GPU_VALIDATION='1'}else{Remove-Item Env:AEVRYND_GPU_VALIDATION -ErrorAction SilentlyContinue}
$directory=Join-Path (Split-Path -Parent $Executable) $(if($GpuValidation){'gameplay-captures-gbv'}else{'gameplay-captures-normal'})
if($GpuValidation){New-Item -ItemType Directory -Force -Path $directory|Out-Null;$env:AEVRYND_FATAL_DIAGNOSTIC_PATH=Join-Path $directory 'gameplay-phase.log';Remove-Item -LiteralPath $env:AEVRYND_FATAL_DIAGNOSTIC_PATH,(Join-Path $directory 'gameplay-fatal-error.txt') -Force -ErrorAction SilentlyContinue}else{Remove-Item Env:AEVRYND_FATAL_DIAGNOSTIC_PATH -ErrorAction SilentlyContinue}
$names=@('first-day.png','third-day.png','god-day.png','first-dusk.png','third-dusk.png','god-dusk.png','first-night.png','third-night.png','god-night.png','palette-building.png','melee-combat.png')
$process=Start-Process -FilePath $Executable -ArgumentList '--capture-demo' -WorkingDirectory (Split-Path -Parent $Executable) -WindowStyle Hidden -PassThru
if(-not$process.WaitForExit(120000)){Stop-Process -Id $process.Id -Force;throw 'Gameplay Lab capture timed out'}
if($process.ExitCode-ne 0){throw "Gameplay Lab capture failed: $($process.ExitCode)"}
Add-Type -AssemblyName System.Drawing
$hashes=@{}
foreach($name in $names){$path=Join-Path $directory $name;if(-not(Test-Path -LiteralPath $path)-or(Get-Item $path).Length-lt 24000){throw "Missing capture: $name"};$bitmap=[System.Drawing.Bitmap]::FromFile($path);try{if($bitmap.Width-ne1280-or$bitmap.Height-ne720){throw "Bad dimensions: $name"};$minimum=255;$maximum=0;for($y=20;$y-lt720;$y+=60){for($x=20;$x-lt1280;$x+=60){$c=$bitmap.GetPixel($x,$y);$v=[int](($c.R+$c.G+$c.B)/3);$minimum=[Math]::Min($minimum,$v);$maximum=[Math]::Max($maximum,$v)}};if($maximum-$minimum-lt35){throw "Low variance: $name"}}finally{$bitmap.Dispose()};$sha=[System.Security.Cryptography.SHA256]::Create();try{$hashes[[BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($path)))]=$true}finally{$sha.Dispose()}}
if($hashes.Count-lt11){throw 'Gameplay captures were not unique'}
$receipt=Get-Content -Raw -LiteralPath (Join-Path $directory 'gameplay-receipt.json')|ConvertFrom-Json
$poseReceipt=Get-Content -Raw -LiteralPath (Join-Path $directory 'gameplay-pose-receipt.json')|ConvertFrom-Json
$grabReceipt=Get-Content -Raw -LiteralPath (Join-Path $directory 'gameplay-grab-receipt.json')|ConvertFrom-Json
