$paletteUiReceipt=Get-Content -Raw -LiteralPath (Join-Path $directory 'gameplay-palette-ui-receipt.json')|ConvertFrom-Json
if($environmentReceipt.runId-ne$receipt.runId-or$environmentReceipt.source-ne'GameplayShowcaseEnvironment3D'-or$environmentReceipt.worldHash-eq0-or$environmentReceipt.descriptors-ne156-or$environmentReceipt.submittedDescriptors-ne$environmentReceipt.descriptors-or$environmentReceipt.executionObserved-ne1-or$environmentReceipt.counterDeltas.Count-ne10-or@($environmentReceipt.counterDeltas|Where-Object{$_-le0}).Count-ne0-or$environmentReceipt.releasedDescriptors-ne$environmentReceipt.descriptors-or$environmentReceipt.retainedBytesAfterRelease-ne0){throw 'Gameplay showcase environment execution/release receipt gate failed'}
if($environmentCollisionReceipt.runId-ne$receipt.runId-or$environmentCollisionReceipt.source-ne'EnvironmentCollisionStreaming3D'-or$environmentCollisionReceipt.stateHash-eq0-or$environmentCollisionReceipt.descriptors-ne156-or$environmentCollisionReceipt.solidDescriptors-ne91-or$environmentCollisionReceipt.nonSolidDescriptors-ne65-or$environmentCollisionReceipt.activePartitions-ne1-or$environmentCollisionReceipt.activeColliders-ne91-or$environmentCollisionReceipt.activePhysicsBodies-ne91-or$environmentCollisionReceipt.activations-lt2-or$environmentCollisionReceipt.deactivations-lt1-or$environmentCollisionReceipt.failedActivations-ne0-or$environmentCollisionReceipt.rollbacks-ne0-or$environmentCollisionReceipt.stableIdEvidence-ne1-or$environmentCollisionReceipt.rayEvidence-ne1-or$environmentCollisionReceipt.meleeQueryEvidence-ne1-or$environmentCollisionReceipt.reloadStable-ne1-or$environmentCollisionReceipt.releasedDescriptors-ne156-or$environmentCollisionReceipt.releasedColliders-ne91-or$environmentCollisionReceipt.releasedPhysicsBodies-ne91-or$environmentCollisionReceipt.retainedBytesAfterRelease-ne0-or$environmentCollisionReceipt.activeCollidersAfterRelease-ne0-or$environmentCollisionReceipt.activePhysicsBodiesAfterRelease-ne0){throw 'Gameplay environment collision semantic/streaming/release receipt gate failed'}
if($paletteUiReceipt.runId-ne$receipt.runId-or$paletteUiReceipt.source-ne'GameplayObjectPaletteUi3D'-or$paletteUiReceipt.categories-ne6-or$paletteUiReceipt.drawnFrames-lt11-or$paletteUiReceipt.pointerDowns-lt1-or$paletteUiReceipt.drags-lt1-or$paletteUiReceipt.previews-lt1-or$paletteUiReceipt.commits-lt1-or$paletteUiReceipt.deterministicHash-eq0){throw 'Gameplay palette UI draw/pointer transaction receipt gate failed'}
if($grabReceipt.runId-ne$receipt.runId-or$grabReceipt.source-ne'GameplayLabGrab'-or$grabReceipt.activeAtStop-ne0-or$grabReceipt.pickAttempts-lt1-or$grabReceipt.grabBegins-lt1-or$grabReceipt.grabHoldSteps-lt1-or$grabReceipt.releaseDrops-lt1){throw 'Gameplay grab receipt gate failed'}
if($poseReceipt.runId-ne$receipt.runId-or$poseReceipt.source-ne'GameplayLabSemanticSkinning'-or$poseReceipt.female.Count-ne11-or$poseReceipt.male.Count-ne11-or@($poseReceipt.female|Select-Object -Unique).Count-ne11-or@($poseReceipt.male|Select-Object -Unique).Count-ne11){throw 'Semantic F2/M2 pose receipt failed'}
if($characterReceipt.runId-ne$receipt.runId-or$characterReceipt.source-ne'GameplayLabCharacterPresentation'-or$characterReceipt.captures.Count-ne11){throw 'Character per-capture receipt identity failed'}
if($receipt.sourceFingerprint-ne$env:AEVRYND_EXPECTED_CHARACTER_FINGERPRINT-or$receipt.sourceFingerprintPassed-ne1-or$characterReceipt.sourceFingerprint-ne$env:AEVRYND_EXPECTED_CHARACTER_FINGERPRINT-or$releaseReceipt.sourceFingerprint-ne$env:AEVRYND_EXPECTED_CHARACTER_FINGERPRINT){throw 'Character runtime build fingerprint gate failed'}
if($releaseReceipt.runId-ne$receipt.runId-or$releaseReceipt.source-ne'GameplayLabCharacterRelease'-or$releaseReceipt.residentSkinnedMeshes-ne0-or$releaseReceipt.residentSkinnedMeshBytes-ne0-or$releaseReceipt.residentMaterialTextureSets-ne0-or$releaseReceipt.residentMaterialTextureReferences-ne0-or$releaseReceipt.skinnedMeshReleases-lt4-or$releaseReceipt.engineTrimCount-lt1-or$releaseReceipt.gameTrimCount-lt1-or$releaseReceipt.gameReclaimableBytes-ne0){throw 'Character resource release/trim gate failed'}
for($index=0;$index-lt$characterReceipt.captures.Count;$index++){$capture=$characterReceipt.captures[$index];$expectedBody=if($capture.camera-eq'first'){0}else{9};if($capture.bodyMaterialSlots-ne$expectedBody-or$capture.weaponMaterialRanges-ne2-or$capture.weaponAnchorError-gt0.001){throw "Character material/socket capture gate failed: $($capture.name)"}}
$firstCaptures=@($characterReceipt.captures|Where-Object{$_.camera-eq'first'});if($firstCaptures.Count-ne3-or@($firstCaptures|Where-Object{$_.character-eq'female-f2'}).Count-lt1-or@($firstCaptures|Where-Object{$_.character-eq'male-m2'}).Count-lt1){throw 'First-person female/male viewmodel coverage missing'};foreach($capture in $firstCaptures){if($capture.weaponScreenCoverage-lt0.02-or$capture.weaponScreenCoverage-gt0.06-or$capture.weaponCenterExcluded-ne1-or$capture.weaponNearClipClear-ne1-or$capture.weaponHudOverlap-ne0-or$capture.gripEdgeAnchored-ne1-or$capture.bladeAboveGrip-ne1){throw "First-person viewmodel projected bounds/grip gate failed: $($capture.name) coverage=$($capture.weaponScreenCoverage) grip=($($capture.weaponGripX),$($capture.weaponGripY)) bladeY=$($capture.weaponBladeY)"}}
if(@($characterReceipt.captures|Where-Object{$_.character-eq'female-f2'}).Count-ne5-or@($characterReceipt.captures|Where-Object{$_.character-eq'male-m2'}).Count-ne6-or@($characterReceipt.captures|Where-Object{$_.crouch-eq1}).Count-ne1-or@($characterReceipt.captures|Where-Object{$_.attack-eq1}).Count-ne1){throw 'Character female/male/crouch/attack capture coverage failed'}
if($receipt.source-ne'GameplayLabFramebuffer'-or$receipt.entry-ne'--capture-demo'-or$receipt.runId-notmatch'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'-or$receipt.captures-ne11-or$receipt.entities-lt18-or$receipt.physicsBodies-lt19-or$receipt.physicsSteps-ne$receipt.ticks-or$receipt.cameraSwitches-lt3-or$receipt.jumps-lt1-or$receipt.crouches-lt1-or$receipt.palettePreviews-lt1-or$receipt.paletteValidPreviews-lt1-or$receipt.paletteInvalidPreviews-lt1-or$receipt.selectedCategory-ne5-or$receipt.paletteCommits-lt1-or$receipt.combatSweeps-lt3-or$receipt.combatHits-ne3-or$receipt.combatKills-ne1-or$receipt.monsterHealth-ne0-or$receipt.animationState-ne8-or$receipt.monsterAnimationState-ne10-or$receipt.corpseVisible-ne1-or$receipt.femaleGpuDraws-lt1-or$receipt.maleGpuDraws-lt1-or$receipt.weaponPbrDraws-lt11-or$receipt.femaleModelIdentity-eq0-or$receipt.maleModelIdentity-eq0-or$receipt.femaleModelIdentity-eq$receipt.maleModelIdentity-or$receipt.femalePoseHash-eq0-or$receipt.malePoseHash-eq0-or[Math]::Abs($receipt.minimumControllerHeight-1.15)-gt0.001-or$receipt.headroomRejected-lt1-or$receipt.crouchFeetInvariant-ne1-or$receipt.weaponAttachmentPassed-ne1-or$receipt.weaponHitWindowEvidence-ne1-or$receipt.weaponAnimationSyncPassed-ne1-or$receipt.maximumWeaponPhaseError-gt0.035-or$receipt.firstPersonBodyHidden-ne1-or$receipt.weaponTrajectoryHash-eq0-or$receipt.attackTrajectoryHashes.Count-ne3-or@($receipt.attackTrajectoryHashes|Select-Object -Unique).Count-ne3-or$receipt.characterMaterialCount-ne18-or$receipt.characterMaterialLoadFailures-ne0-or$receipt.skinnedGroups-lt1-or$receipt.skinnedInstances-lt2-or$receipt.rejectedSkinnedGroups-ne0-or$receipt.residentSkinnedMeshBytes-lt1-or$receipt.lighting.Count-ne3-or$receipt.gpuErrors-ne0-or$receipt.gpuWarnings-ne0){throw 'Gameplay receipt gate failed'}
$runtimeRoot=Split-Path -Parent $Executable
foreach($relative in @('assets/material-packs/original/LICENSE.txt','assets/material-packs/original/manifest.json','assets/model-packs/CC0-HUMAN-BASE-MESHES.md','assets/material-packs/original/female.materials.json','assets/material-packs/original/male.materials.json')){if(-not(Test-Path -LiteralPath (Join-Path $runtimeRoot $relative))){throw "Missing packaged CC0 provenance/material sidecar: $relative"}}
foreach($relative in @('assets/environment-material-packs/LICENSE.md','assets/environment-material-packs/ambientcg/ground037/1k/Ground037_1K-JPG_Color.jpg','assets/environment-material-packs/ambientcg/woodsiding006/1k/WoodSiding006_1K-JPG_Color.jpg','assets/environment-model-packs/poly-haven/quiver_tree_02/quiver_tree_02.aemesh','assets/environment-model-packs/poly-haven/rock_09/rock_09.aemesh')){if(-not(Test-Path -LiteralPath (Join-Path $runtimeRoot $relative))){throw "Missing packaged showcase CC0 asset: $relative"}}
$environmentMaterialRoot=Join-Path $runtimeRoot 'assets/environment-material-packs';$environmentModelRoot=Join-Path $runtimeRoot 'assets/environment-model-packs';$characterMaterialRoot=Join-Path $runtimeRoot 'assets/material-packs/original'
$materialLicense=Get-Content -Raw -LiteralPath (Join-Path $environmentMaterialRoot 'LICENSE.md');$modelLicense=Get-Content -Raw -LiteralPath (Join-Path $environmentModelRoot 'LICENSE.md');if($materialLicense-notmatch'CC0 1\.0'-or$modelLicense-notmatch'CC0 1\.0'){throw 'Showcase CC0 license text gate failed'}
$materialManifest=Get-Content -Raw -LiteralPath (Join-Path $environmentMaterialRoot 'material-packs.json')|ConvertFrom-Json;$modelManifest=Get-Content -Raw -LiteralPath (Join-Path $environmentModelRoot 'model-packs.json')|ConvertFrom-Json
if($materialManifest.license-ne'CC0-1.0'-or-not$materialManifest.commercialUse-or$modelManifest.license-ne'CC0-1.0'-or-not$modelManifest.commercialUse){throw 'Showcase CC0 commercial-use manifest gate failed'}
foreach($id in @('ground-037','wood-siding-006','bark-brown-02','aerial-ground-rock')){$pack=@($materialManifest.packs|Where-Object{$_.id-eq$id});if($pack.Count-ne1-or$pack[0].source-notin@('Poly Haven','ambientCG')-or$pack[0].sourceUrl-notmatch'^https://'-or$pack[0].licenseUrl-notmatch'^https://'){throw "Showcase material provenance gate failed: $id"}}
foreach($id in @('quiver-tree-02','rock-09')){$pack=@($modelManifest.packs|Where-Object{$_.id-eq$id});if($pack.Count-ne1-or$pack[0].source-ne'Poly Haven'-or$pack[0].sourceUrl-notmatch'^https://'-or$pack[0].licenseUrl-notmatch'^https://'){throw "Showcase model provenance gate failed: $id"};$mesh=Join-Path $environmentModelRoot $pack[0].mesh;if(-not(Test-Path -LiteralPath $mesh)-or(Get-Item -LiteralPath $mesh).Length-lt1024){throw "Showcase model payload gate failed: $id"}}
$characterManifest=Get-Content -Raw -LiteralPath (Join-Path $characterMaterialRoot 'manifest.json')|ConvertFrom-Json;if($characterManifest.license-ne'CC0-1.0'){throw 'Character material CC0 manifest gate failed'};foreach($material in $characterManifest.materials){foreach($channel in $material.channels.PSObject.Properties){$entry=$channel.Value;$path=Join-Path $characterMaterialRoot $entry.path;if(-not(Test-Path -LiteralPath $path)-or(Get-Item -LiteralPath $path).Length-ne$entry.bytes-or(Get-Sha256Hex $path)-ne$entry.sha256.ToLowerInvariant()){throw "Character material payload hash gate failed: $($material.id)/$($channel.Name)"}}}
if($receipt.physicsSteps-ne$receipt.ticks-or$receipt.authoritativePhysicsTick-ne240-or$receipt.authoritativePhysicsSteps-ne$receipt.authoritativePhysicsTick-or$receipt.ticks-lt$receipt.authoritativePhysicsTick){throw 'Gameplay receipt did not preserve live and authoritative physics telemetry'}
if($GpuValidation-and($receipt.gpuValidationRequested-ne1-or$receipt.gpuValidationAvailable-ne1-or$receipt.gpuValidationExecuted-ne1-or$receipt.debugLayerEnabled-ne1-or$receipt.gpuValidationPassed-ne1)){throw 'Gameplay GPU validation was requested but did not execute and pass'}
if($GpuValidation-and(-not((Get-Content -Raw -LiteralPath (Join-Path $directory 'gameplay-phase.log')).Contains("BuildFingerprint:$($env:AEVRYND_EXPECTED_CHARACTER_FINGERPRINT)")))){throw 'GBV phase fingerprint gate failed'}
if(-not$GpuValidation-and($receipt.gpuValidationRequested-ne0-or$receipt.gpuValidationAvailable-ne0-or$receipt.gpuValidationExecuted-ne0-or$receipt.debugLayerEnabled-ne0-or$receipt.gpuValidationPassed-ne0)){throw 'Normal Gameplay Lab capture unexpectedly enabled GPU validation'}
$first=$receipt
$process=Start-Process -FilePath $Executable -ArgumentList '--capture-demo' -WorkingDirectory (Split-Path -Parent $Executable) -WindowStyle Hidden -PassThru
if(-not$process.WaitForExit(120000)){Stop-Process -Id $process.Id -Force;throw 'Second deterministic capture timed out'}
if($process.ExitCode-ne0){throw "Second deterministic capture failed: $($process.ExitCode)"}
$second=Get-Content -Raw -LiteralPath (Join-Path $directory 'gameplay-receipt.json')|ConvertFrom-Json
$secondEnvironment=Get-Content -Raw -LiteralPath (Join-Path $directory 'gameplay-environment-receipt.json')|ConvertFrom-Json
$secondEnvironmentCollision=Get-Content -Raw -LiteralPath (Join-Path $directory 'gameplay-environment-collision-receipt.json')|ConvertFrom-Json
$secondPaletteUi=Get-Content -Raw -LiteralPath (Join-Path $directory 'gameplay-palette-ui-receipt.json')|ConvertFrom-Json
if($first.runId-eq$second.runId){throw 'Capture run identifier was reused'}
$fields=@('captures','entities','physicsBodies','authoritativePhysicsTick','authoritativePhysicsSteps','cameraSwitches','jumps','crouches','palettePreviews','paletteCommits','combatSweeps','combatHits','combatKills','monsterHealth','animationState','weaponAnimationSyncPassed','firstPersonBodyHidden','characterMaterialCount','characterMaterialLoadFailures')
foreach($field in $fields){if($first.$field-ne$second.$field){throw "Nondeterministic gameplay telemetry: $field"}}
foreach($field in @('worldHash','descriptors','submittedDescriptors','executionObserved','releasedDescriptors','retainedBytesAfterRelease')){if($environmentReceipt.$field-ne$secondEnvironment.$field){throw "Nondeterministic environment telemetry: $field"}}
foreach($field in @('stateHash','descriptors','solidDescriptors','nonSolidDescriptors','activePartitions','activeColliders','activePhysicsBodies','activations','deactivations','failedActivations','rollbacks','stableIdEvidence','rayEvidence','meleeQueryEvidence','reloadStable','releasedDescriptors','releasedColliders','releasedPhysicsBodies','retainedBytesAfterRelease','activeCollidersAfterRelease','activePhysicsBodiesAfterRelease')){if($environmentCollisionReceipt.$field-ne$secondEnvironmentCollision.$field){throw "Nondeterministic environment collision telemetry: $field"}}
foreach($field in @('categories','pointerDowns','drags','previews','commits','invalidPlacements','cancels','deterministicHash')){if($paletteUiReceipt.$field-ne$secondPaletteUi.$field){throw "Nondeterministic palette UI telemetry: $field"}}
if([Math]::Abs([int64]$first.ticks-[int64]$second.ticks)-gt1-or[Math]::Abs([int64]$first.physicsSteps-[int64]$second.physicsSteps)-gt1){throw 'Capture completion varied by more than one presentation frame'}
$captureEntries=@();foreach($name in $names){$path=Join-Path $directory $name;$sha=[System.Security.Cryptography.SHA256]::Create();try{$captureEntries+=@{name=$name;sha256=([BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($path))).Replace('-','').ToLowerInvariant())}}finally{$sha.Dispose()}}
@{runId=$second.runId;source='GameplayLabFramebuffer';captures=$captureEntries;telemetry=$second}|ConvertTo-Json -Depth 5|Set-Content -Encoding utf8 -LiteralPath (Join-Path $directory 'gameplay-capture-receipt.json')
Write-Output "captures=11 unique=11 deterministic=2 entities=$($receipt.entities) physics=$($receipt.physicsBodies) sweeps=$($receipt.combatSweeps) hits=$($receipt.combatHits) kills=$($receipt.combatKills)"
